<script setup lang="ts">
import {keywordError} from './adsKeywordValidation'
import {adDisplayData,internalAdId} from './adDisplay'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('AdsCreatePage')

import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Refresh,Search,Plus,Delete} from '@element-plus/icons-vue'
import {api} from './session'
const props=defineProps<{mode:string,profileId:string,profiles?:any[],campaign?:any,draftKey?:string}>()
const emit=defineEmits(['close','created'])
const initialDraft=ref('')
const profiles=ref<any[]>(props.profiles||[])
const profile=ref(props.profileId),options=ref<any>({campaigns:[]}),advanced=ref<any>({portfolios:[],audiences:[],warnings:[]}),error=ref(''),busy=ref(false),optionsBusy=ref(false)
const isCampaign=props.mode==='campaign',title=isCampaign?'创建广告活动':'创建广告组'
const campaignId=ref(props.campaign?.id||''),name=ref(''),defaultBid=ref<number|undefined>(),state=ref('ENABLED'),targeting=ref('AUTO')
const campaign=ref<any>({name:'',dailyBudget:undefined,portfolioId:null,startDate:'',endDate:null,biddingStrategy:'LEGACY_FOR_SALES',site:'ALL',offAmazonStrategy:'MAXIMIZE_REACH',placementTop:0,placementRest:0,placementProduct:0,placementBusiness:0,audiences:[],note:''})
const auto=ref<any[]>([{type:'QUERY_HIGH_REL_MATCHES',label:'紧密匹配',enabled:true,bid:undefined},{type:'QUERY_BROAD_REL_MATCHES',label:'宽泛匹配',enabled:true,bid:undefined},{type:'ASIN_SUBSTITUTE_RELATED',label:'同类商品',enabled:true,bid:undefined},{type:'ASIN_ACCESSORY_RELATED',label:'关联商品',enabled:true,bid:undefined}])
function changeAutoBid(row:any,value:number|undefined){if(value===(row.bid??defaultBid.value))return;row.bid=value}
const selected=ref<any[]>([]),rows=ref<any[]>([]),total=ref(0),page=ref(1),pageSize=ref(25),q=ref(''),productsBusy=ref(false),pickTab=ref('search'),paste=ref(''),pasteKind=ref('sku'),unresolved=ref<any[]>([])
const manualType=ref('keywords'),keywordText=ref(''),keywordMatches=ref<string[]>(['EXACT']),keywords=ref<any[]>([]),targetText=ref(''),targets=ref<any[]>([]),negativeText=ref(''),negativeMatches=ref<string[]>(['NEGATIVE_EXACT']),negativeKeywords=ref<any[]>([]),negativeAsinText=ref(''),negativeAsins=ref<string[]>([])
const keywordSuggestions=ref<Record<string,any>>({}),chosenKeywords=ref<any[]>([]),bulkBid=ref<number|undefined>(),bulkScope=ref('all')
const bulkPercent=ref<number|undefined>(),bulkDirection=ref('increase')
const bidLevels=[['low','低档'],['mid','中档'],['high','高档']]
const keywordKey=(k:any)=>JSON.stringify([k.text.trim().replace(/\s+/g,' ').toLowerCase(),k.match])
const batchKeywords=computed(()=>bulkScope.value==='all'?keywords.value:chosenKeywords.value.filter(k=>keywords.value.includes(k)))
const suggestions=ref<any>({}),suggestBusy=ref(false),preview=ref<any>(null),previewOpen=ref(false),result=ref<any>(null)
const activeProfile=computed(()=>profiles.value.find(p=>p.id===profile.value)),currency=computed(()=>activeProfile.value?.currency||options.value.currency||'EUR')
const parent=computed(()=>options.value.campaigns.find((c:any)=>c.id===campaignId.value))
const selectedSkus=computed(()=>new Set(selected.value.map(r=>r.sku)))
const submitting=computed(()=>result.value?.status==='sending')
const strategyLabels:Record<string,string>={LEGACY_FOR_SALES:'动态竞价－只降低',AUTO_FOR_SALES:'动态竞价－提高和降低',MANUAL:'固定竞价'}
const matchLabels:Record<string,string>={EXACT:'精准匹配',PHRASE:'词组匹配',BROAD:'广泛匹配',NEGATIVE_EXACT:'否定精准',NEGATIVE_PHRASE:'否定词组'}
const placements=[['placementTop','搜索结果顶部（首页）'],['placementRest','搜索结果的其余位置'],['placementProduct','商品页面'],['placementBusiness','亚马逊企业购']]
const money=(v:any)=>v==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:currency.value}).format(v)
let poll:ReturnType<typeof setInterval>|undefined,request=0,alive=true
const taskKey=()=>`ads-create:${profile.value}:${props.mode}${props.draftKey?':'+props.draftKey:''}`
async function loadProducts(){const id=++request;productsBusy.value=true;try{const r=await api('/advertising/create/products?'+new URLSearchParams({profile_id:profile.value,q:q.value,page:String(page.value),page_size:String(pageSize.value)}));if(id===request){rows.value=r.rows;total.value=r.total}}catch(e){error.value=(e as Error).message}finally{if(id===request)productsBusy.value=false}}
function searchProducts(){page.value=1;loadProducts()}
async function loadOptions(){optionsBusy.value=true;try{options.value=await api('/advertising/create/options?profile_id='+profile.value);campaign.value.startDate=options.value.today;selectCampaign();await loadProducts()}catch(e){error.value=(e as Error).message}finally{optionsBusy.value=false}}
async function loadAdvanced(){optionsBusy.value=true;try{advanced.value=await api('/advertising/create/advanced-options?profile_id='+profile.value)}catch(e){error.value=(e as Error).message}finally{optionsBusy.value=false}}
function selectCampaign(){if(!isCampaign&&parent.value?.targeting){targeting.value=parent.value.targeting;clearSuggestions()}}
function clearSuggestions(){suggestions.value={};keywordSuggestions.value={};cachedContext='';scheduleSuggestions()}
async function changeProfile(){selected.value=[];campaignId.value='';campaign.value.portfolioId=null;campaign.value.audiences=[];advanced.value={portfolios:[],audiences:[],warnings:[]};clearSuggestions();await loadOptions()}
function changeSite(){if(campaign.value.site==='AMAZON_BUSINESS'){campaign.value.audiences=[];campaign.value.placementBusiness=0}}
function audienceChange(id:string){campaign.value.audiences=id?[{shopperCohortType:'AUDIENCE_SEGMENT',percentage:0,audienceSegments:[{audienceId:id}]}]:[]}
function addProduct(row:any){if(selectedSkus.value.has(row.sku))return;if(selected.value.length>=100){ElMessage.warning('一次最多选择100个商品');return}selected.value.push({...row});clearSuggestions()}
function removeProduct(sku:string){selected.value=selected.value.filter(r=>r.sku!==sku);clearSuggestions()}
const lines=(s:string)=>[...new Set(s.split(/\r?\n/).map(s=>s.trim()).filter(Boolean))]
async function resolvePaste(){const values=lines(paste.value);if(!values.length||values.length>100){ElMessage.warning('请输入1至100行 SKU 或 ASIN');return}productsBusy.value=true;try{const r=await api('/advertising/create/products/resolve',{profile_id:profile.value,kind:pasteKind.value,values});r.rows.forEach(addProduct);unresolved.value=r.unresolved;if(!r.unresolved.length)paste.value=''}catch(e){error.value=(e as Error).message}finally{productsBusy.value=false}}
const keywordInputError=ref('')
function addKeywords(negative=false){
 if(!negative)keywordInputError.value=''
 const input=negative?negativeText:keywordText,values=negative?negativeKeywords:keywords,matches=negative?negativeMatches.value:keywordMatches.value
 const items=lines(input.value).map(t=>t.replace(/\s+/g,' '));if(!items.length)return
 if(!matches.length){ElMessage.warning('请选择至少一种匹配方式');return}
 if(!negative&&(!defaultBid.value||defaultBid.value<0.02)){ElMessage.warning('请先填写默认竞价');return}
 if(!negative){const invalid=items.map(text=>({text,error:keywordError(text)})).filter(i=>i.error);if(invalid.length){keywordInputError.value=invalid.slice(0,5).map(i=>i.text+'：'+i.error).join('；');return}}
 if(negative&&items.some(s=>s.length>250)){ElMessage.warning('单个关键词最多250个字符');return}
 const seen=new Set(values.value.map(keywordKey)),added:any[]=[],duplicates:string[]=[]
 for(const text of items)for(const match of matches){const row={text,match,bid:negative?null:defaultBid.value};const key=keywordKey(row);if(seen.has(key))duplicates.push(text+' · '+matchLabels[match]);else{seen.add(key);added.push(row)}}
 if(values.value.length+added.length>1000){ElMessage.warning('最多添加1000个关键词与匹配方式组合');return}
 values.value.push(...added);input.value=''
 if(duplicates.length)ElMessage.warning('已存在，未重复添加：'+duplicates.slice(0,3).join('；')+(duplicates.length>3?` 等${duplicates.length}项`:''))
}
function applyKeywordBids(level:string){
 const rows=batchKeywords.value;if(!rows.length){ElMessage.warning('请先选择关键词');return}
 if(level==='custom'&&(!bulkBid.value||bulkBid.value<0.02||bulkBid.value>10000)){ElMessage.warning('请输入0.02至10000的竞价');return}
 let applied=0;for(const row of rows){const value=level==='custom'?bulkBid.value:keywordSuggestions.value[keywordKey(row)]?.[level];if(value!=null){row.bid=value;applied++}}
 if(applied<rows.length)ElMessage.warning(`已应用${applied}项，${rows.length-applied}项暂无建议价，保留原竞价`)
 else ElMessage.success(`已更新${applied}项竞价`)
}
function applyKeywordPercent(){
 const rows=batchKeywords.value,percent=bulkPercent.value
 if(!rows.length){ElMessage.warning('请先选择关键词');return}
 if(percent==null||!Number.isFinite(percent)||percent<=0||percent>10000||(bulkDirection.value==='decrease'&&percent>=100)){ElMessage.warning('请输入有效百分比，降低幅度必须小于100%');return}
 const factor=10000+(bulkDirection.value==='decrease'?-1:1)*Math.round(percent*100)
 const values=rows.map(row=>Math.round(Math.round(Number(row.bid??defaultBid.value)*100)*factor/10000)/100)
 if(values.some(value=>!Number.isFinite(value)||value<0.02||value>10000)){ElMessage.warning('调整后竞价须在0.02至10000之间，本次未应用，请调整百分比或原竞价');return}
 rows.forEach((row,index)=>row.bid=values[index])
 ElMessage.success(`已${bulkDirection.value==='decrease'?'降低':'提高'}${rows.length}项竞价`)
}
function addAsins(negative=false){const input=negative?negativeAsinText:targetText;const items=lines(input.value.toUpperCase());if(items.some(s=>!/^\w{10}$/.test(s)||!/^[A-Z0-9]+$/.test(s))){ElMessage.warning('ASIN须为10位字母或数字，每行一个');return}for(const asin of items){if(negative){if(!negativeAsins.value.includes(asin))negativeAsins.value.push(asin)}else if(!targets.value.some(t=>t.asin===asin))targets.value.push({asin,bid:null})}input.value=''}
let suggestionSeq=0,suggestionTimer:ReturnType<typeof setTimeout>|undefined
const suggestionContext=()=>JSON.stringify([profile.value,[...new Set(selected.value.map(r=>r.asin))].sort(),isCampaign?campaign.value.biddingStrategy:parent.value?.strategy,targeting.value])
let cachedContext=''
async function refreshSuggestions(quiet=false){
 const asins=[...new Set<string>(selected.value.map(r=>r.asin))]
 if(asins.some(a=>!a)||!asins.length||asins.length>50){if(!quiet)ElMessage.warning('建议竞价需要选择1至50个已知ASIN的商品');return}
 const id=++suggestionSeq,context=suggestionContext(),manual=targeting.value==='MANUAL'
 if(cachedContext!==context){keywordSuggestions.value={};suggestions.value={};cachedContext=context}
 const pending=manual?keywords.value.filter(k=>!quiet||!(keywordKey(k) in keywordSuggestions.value)).map(({text,match})=>({text,match})):[]
 if(manual&&!pending.length)return
 suggestBusy.value=true
 try{
  const base={profile_id:profile.value,asins,strategy:isCampaign?campaign.value.biddingStrategy:(parent.value?.strategy||'LEGACY_FOR_SALES')}
  if(manual){for(let i=0;i<pending.length;i+=100){const r=await api('/advertising/create/suggestions',{...base,keywords:pending.slice(i,i+100)});if(id!==suggestionSeq||!alive||context!==suggestionContext())return;for(const k of r.keywords||[])keywordSuggestions.value[keywordKey(k)]=k.suggestion}}
  else {const r=await api('/advertising/create/suggestions',base);if(id!==suggestionSeq||!alive||context!==suggestionContext())return;suggestions.value=r}
  if(!quiet)ElMessage.success('建议竞价已更新')
 }catch(e){if(id===suggestionSeq){if(quiet)ElMessage.warning('建议竞价暂未取得，可点击刷新重试');else error.value=(e as Error).message}}
 finally{if(id===suggestionSeq)suggestBusy.value=false}
}
function scheduleSuggestions(){clearTimeout(suggestionTimer);suggestionSeq++;suggestBusy.value=false;suggestionTimer=setTimeout(()=>refreshSuggestions(true),400)}
watch(()=>[suggestionContext(),JSON.stringify(keywords.value.map(keywordKey))],scheduleSuggestions)
function payload(){return {profile_id:profile.value,mode:props.mode,campaign_id:isCampaign?'':campaignId.value,campaign:isCampaign?{...campaign.value,portfolioId:campaign.value.portfolioId||null,endDate:campaign.value.endDate||null}:{},name:name.value,default_bid:defaultBid.value,state:state.value,targeting:targeting.value,products:selected.value.map(p=>({sku:p.sku,asin:p.asin||''})),auto_targets:targeting.value==='AUTO'?auto.value.map(({type,enabled,bid})=>({type,enabled,bid:bid??null})):[],keywords:targeting.value==='MANUAL'?keywords.value:[],targets:targeting.value==='MANUAL'?targets.value:[],negative_keywords:negativeKeywords.value,negative_asins:negativeAsins.value}}
async function showPreview(){error.value='';const invalid=keywords.value.find(k=>keywordError(k.text));if(invalid){error.value=invalid.text+'：'+keywordError(invalid.text);return}if(!name.value.trim()||!defaultBid.value||!selected.value.length||(!isCampaign&&!campaignId.value)){error.value='请填写广告组名称、默认竞价，并选择商品及所属活动';return}if(isCampaign&&(!campaign.value.name.trim()||!campaign.value.dailyBudget)){error.value='请填写广告活动名称和每日预算';return}if([keywordText.value,targetText.value,negativeText.value,negativeAsinText.value,paste.value].some(s=>s.trim())){error.value='仍有未添加的输入内容，请点击对应“添加”按钮或清空后再预览';return}busy.value=true;try{preview.value=await api('/advertising/create/preview',payload());previewOpen.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function pollResult(){const id=result.value?.id;if(!id)return;try{const r=await api('/advertising/create/status/'+id);if(!alive)return;result.value=r;if(r.status==='preview'){if(poll)clearInterval(poll);localStorage.removeItem(taskKey());result.value=null;error.value='该预览尚未提交或已过期，请重新预览后确认';return}if(r.status!=='sending'){if(poll)clearInterval(poll);localStorage.removeItem(taskKey());if(r.status==='succeeded'){ElMessage.success('创建完成');emit('created')}}}catch(e){error.value='创建结果暂时无法读取，后台仍可能在处理。'+(e as Error).message}}
function watchResult(){if(poll)clearInterval(poll);poll=setInterval(pollResult,2500);pollResult()}
async function confirm(){if(!preview.value||busy.value)return;busy.value=true;error.value='';const id=preview.value.id;localStorage.setItem(taskKey(),id);try{result.value=await api('/advertising/create/confirm',{id});previewOpen.value=false;watchResult()}catch(e){previewOpen.value=false;result.value={id,status:'sending'};error.value='正在核对提交结果：'+(e as Error).message;watchResult()}finally{busy.value=false}}
function draftSnapshot(){return JSON.stringify({values:payload(),text:[paste.value,keywordText.value,targetText.value,negativeText.value,negativeAsinText.value]})}
async function canLeave(){if(busy.value){ElMessage.warning('正在处理，请稍后关闭');return false}if(!result.value&&initialDraft.value&&draftSnapshot()!==initialDraft.value){try{await ElMessageBox.confirm('离开后，尚未提交的填写内容将丢失。','关闭创建页面',{confirmButtonText:'离开',cancelButtonText:'继续填写',type:'warning'})}catch{return false}}return true}
async function close(){if(await canLeave())emit('close')}
defineExpose({canLeave})
onMounted(async()=>{if(!profiles.value.length){try{profiles.value=(await api('/advertising/profiles')).profiles}catch(e){error.value=(e as Error).message;return}}if(!profiles.value.some(p=>p.id===profile.value)){error.value='该广告账户不可用，请关闭后重新选择店铺和国家';return}await loadOptions();initialDraft.value=draftSnapshot();const id=localStorage.getItem(taskKey());if(id){result.value={id,status:'sending'};watchResult()}})
onUnmounted(()=>{alive=false;request++;suggestionSeq++;clearTimeout(suggestionTimer);if(poll)clearInterval(poll)})
</script>
<template>
<div class="ads-create">
 <header class="create-heading"><div><h2>{{title}}</h2><p>商品推广 · SP · {{activeProfile?.account}} · {{activeProfile?.country}} · {{currency}}</p></div><el-tag effect="plain">预览后确认创建</el-tag></header>
 <el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/>
 <section v-if="result" class="create-card creation-result">
  <h3>{{result.status==='succeeded'?'创建完成':result.status==='sending'?'正在创建':result.status==='unknown'?'结果待核对':'创建未完成'}}</h3>
  <p>{{result.message}}</p><p v-if="result.current">当前步骤：{{result.current}}</p>
  <el-alert v-if="['failed','unknown'].includes(result.status)" title="已创建的对象和步骤已保留。请同步广告数据核对并补全，不要重新创建同一活动。" type="warning" :closable="false"/>
  <ul><li v-for="(step,i) in result.steps" :key="i">✓ {{step.label}}</li></ul>
  <el-button :icon="Refresh" @click="pollResult">刷新结果</el-button><el-button type="primary" @click="emit('close')">返回广告列表</el-button>
 </section>
 <template v-else>
 <el-form label-position="top" :disabled="busy">
 <section class="create-card"><h3>设置</h3><div class="settings-grid">
  <el-form-item label="店铺 / 国家" required><el-select v-model="profile" @change="changeProfile"><el-option v-for="p in profiles" :key="p.id" :value="p.id" :label="p.account+' · '+p.country"/></el-select></el-form-item>
  <el-form-item v-if="!isCampaign" label="所属广告活动" required><el-select v-model="campaignId" filterable placeholder="请选择广告活动" @change="selectCampaign"><el-option v-for="c in options.campaigns" :key="c.id" :value="c.id" :label="c.name+' · '+(c.targeting==='AUTO'?'自动':'手动')"/></el-select></el-form-item>
  <template v-if="isCampaign">
   <el-form-item label="广告活动名称" required><el-input v-model="campaign.name" maxlength="128" show-word-limit placeholder="请输入广告活动名称"/></el-form-item>
   <el-form-item label="广告组合"><div class="inline-field"><el-select v-model="campaign.portfolioId" clearable filterable placeholder="无组合"><el-option v-for="p in advanced.portfolios" :key="p.portfolioId" :value="String(p.portfolioId)" :label="p.name"/></el-select><el-button :icon="Refresh" :loading="optionsBusy" @click="loadAdvanced" title="获取广告组合和受众选项"/></div></el-form-item>
   <el-form-item :label="'每日预算（'+currency+'）'" required><el-input-number v-model="campaign.dailyBudget" :min="1" :precision="2" :step="1" controls-position="right" placeholder="至少1"/></el-form-item>
   <el-form-item label="开始日期（站点当地日期）" required><el-date-picker v-model="campaign.startDate" type="date" value-format="YYYY-MM-DD" :clearable="false"/></el-form-item>
   <el-form-item label="结束日期"><el-date-picker v-model="campaign.endDate" type="date" value-format="YYYY-MM-DD" placeholder="无结束日期"/></el-form-item>
   <el-form-item class="wide-field" label="备注"><el-input v-model="campaign.note" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="备注仅保存在本地"/></el-form-item>
  </template>
  <el-form-item label="创建完成后的状态"><el-radio-group v-model="state"><el-radio value="ENABLED">开启</el-radio><el-radio value="PAUSED">暂停</el-radio></el-radio-group></el-form-item>
 </div><p v-if="!isCampaign&&parent?.state==='PAUSED'" class="hint">所属活动当前暂停，创建广告组不会自动开启该活动。</p>
 <p v-for="w in advanced.warnings" :key="w" class="warning">{{w}}</p></section>
 <template v-if="isCampaign">
 <section class="create-card"><h3>站点与投放方式</h3>
  <el-form-item label="展示站点"><el-radio-group v-model="campaign.site" @change="changeSite"><el-radio value="ALL">亚马逊及其他网站</el-radio><el-radio value="AMAZON_BUSINESS">亚马逊企业购</el-radio></el-radio-group></el-form-item>
  <el-form-item v-if="campaign.site==='ALL'" label="站外投放设置"><el-radio-group v-model="campaign.offAmazonStrategy"><el-radio value="MAXIMIZE_REACH">扩大受众触达</el-radio><el-radio value="MINIMIZE_SPEND">限制在亚马逊站外的花费</el-radio></el-radio-group></el-form-item>
  <el-form-item label="定向策略" required><el-radio-group v-model="targeting"><el-radio-button value="AUTO">自动投放</el-radio-button><el-radio-button value="MANUAL">手动投放</el-radio-button></el-radio-group></el-form-item>
 </section>
 <section class="create-card"><h3>竞价策略</h3>
  <el-radio-group v-model="campaign.biddingStrategy" class="strategies" @change="clearSuggestions"><el-radio v-for="(label,key) in strategyLabels" :key="key" :value="key">{{label}}</el-radio></el-radio-group>
  <h4>根据广告位调整竞价</h4><div class="settings-grid"><el-form-item v-for="[key,label] in placements.filter(([k])=>campaign.site==='ALL'||k!=='placementBusiness')" :key="key" :label="label"><el-input-number v-model="campaign[key]" :min="0" :max="900" :precision="0" :step="10" controls-position="right"/> %</el-form-item></div>
  <el-form-item v-if="campaign.site==='ALL'" label="受众加价"><div class="inline-field"><el-select :model-value="campaign.audiences[0]?.audienceSegments[0]?.audienceId||''" clearable filterable placeholder="不对受众提价" @change="audienceChange"><el-option v-for="a in advanced.audiences" :key="a.audienceId" :value="a.audienceId" :label="a.audienceResolved||a.audienceId"/></el-select><el-button :icon="Refresh" :loading="optionsBusy" @click="loadAdvanced">获取受众</el-button><template v-if="campaign.audiences.length"><el-input-number v-model="campaign.audiences[0].percentage" :min="0" :max="900" :precision="0"/> %</template></div></el-form-item>
 </section></template>
 <section class="create-card"><h3>广告组设置</h3><div class="settings-grid"><el-form-item label="广告组名称" required><el-input v-model="name" maxlength="255" show-word-limit placeholder="请输入广告组名称"/></el-form-item></div></section>
 <section class="create-card"><h3>添加需投放广告的商品 <span class="hint">已选择 {{selected.length}} / 100</span></h3>
  <p class="hint">从此店铺已同步的商品与广告资料选择，或批量输入 SKU。商品是否可投放以亚马逊创建结果为准。</p>
  <div class="product-columns"><div>
   <el-radio-group v-model="pickTab" size="small"><el-radio-button value="search">搜索商品</el-radio-button><el-radio-button value="paste">输入列表</el-radio-button></el-radio-group>
   <template v-if="pickTab==='search'"><div class="product-search"><el-input v-model="q" clearable placeholder="SKU / ASIN / FNSKU / 标题 / 品名" @keyup.enter="searchProducts"/><el-button :icon="Search" @click="searchProducts">搜索</el-button></div>
   <div class="product-list" v-loading="productsBusy"><div class="product-list-head"><span>可选商品</span><el-button link type="primary" @click="rows.forEach(addProduct)">添加本页</el-button></div>
    <div class="product-row" v-for="r in rows" :key="r.sku"><el-image v-if="r.image" :src="r.image" fit="contain"/><div v-else class="no-image">暂无图片</div><div class="product-info"><b>{{r.product_name||r.title||r.sku}}</b><span>SKU：{{r.sku}}</span><span>ASIN：{{r.asin||'—'}}　可售库存：{{r.available??'—'}}</span></div><el-button size="small" :disabled="selectedSkus.has(r.sku)" @click="addProduct(r)">{{selectedSkus.has(r.sku)?'已添加':'添加'}}</el-button></div>
    <el-empty v-if="!rows.length&&!productsBusy" description="暂无匹配商品，可通过输入列表添加SKU" :image-size="60"/>
   </div><AppPagination :total="total" v-model:current-page="page" @change="loadProducts" v-model:page-size="pageSize"/>
   </template><template v-else><el-radio-group v-model="pasteKind"><el-radio value="sku">SKU</el-radio><el-radio value="asin">ASIN（匹配本店SKU）</el-radio></el-radio-group><el-input v-model="paste" type="textarea" :rows="12" placeholder="每行一个，最多100行"/><el-button :loading="productsBusy" @click="resolvePaste">添加到已选商品</el-button><p v-for="r in unresolved" :key="r.value" class="warning">{{r.value}}：{{r.reason}}</p></template>
  </div><div class="product-list selected-list"><div class="product-list-head"><b>已选商品 {{selected.length}}</b><el-button link @click="selected=[];clearSuggestions()">全部移除</el-button></div><div class="product-row" v-for="r in selected" :key="r.sku"><el-image v-if="r.image" :src="r.image" fit="contain"/><div class="product-info"><b>{{r.product_name||r.title||r.sku}}</b><span>{{r.sku}}</span><span>{{r.asin||'ASIN尚未核实'}}</span><span v-if="r.unverified" class="warning">未在本地找到，提交时由亚马逊校验</span></div><el-button link :icon="Delete" @click="removeProduct(r.sku)" aria-label="移除商品"/></div><el-empty v-if="!selected.length" description="请添加商品" :image-size="80"/></div></div>
 </section>
 <section class="create-card"><h3>投放设置 · {{targeting==='AUTO'?'自动投放':'手动投放'}}</h3>
 <div class="target-default"><el-form-item :label="'默认竞价（'+currency+'）'" required><el-input-number v-model="defaultBid" :min="0.02" :max="10000" :precision="2" :step="0.01" controls-position="right" aria-label="默认竞价"/></el-form-item><span class="hint">{{targeting==='AUTO'?'下方四类自动投放自动带入此竞价，单独调整后使用各自竞价。':'添加关键词时使用此竞价，可逐项或批量调整。'}}</span></div>
 <template v-if="targeting==='AUTO'"><div class="section-actions"><span class="hint">四类定向可分别设置开关和竞价。</span><el-button :icon="Refresh" :loading="suggestBusy" @click="refreshSuggestions(false)">刷新建议竞价</el-button><TableReset table-key="AdsCreatePage/table-1"/></div>
 <template v-if="true"><el-table border data-width-key="AdsCreatePage/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="auto"><el-table-column :column-key="'column-1'" label="开启" :width="tableWidths.width('table-1', 'column-1', '85')"><template #default="{row}"><el-switch v-model="row.enabled"/></template></el-table-column><el-table-column :column-key="'label'" :width="tableWidths.width('table-1', 'label', undefined)" prop="label" label="定向组" min-width="120"/><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-1', 'column-3', undefined)" :label="'建议竞价（'+currency+'）'" align="center" min-width="240"><template #default="{row}"><template v-if="suggestions[row.type]">{{money(suggestions[row.type].mid)}} <span class="hint">({{suggestions[row.type].low}}–{{suggestions[row.type].high}})</span><el-dropdown @command="(key:string)=>row.bid=suggestions[row.type][key]"><el-button link type="primary">应用 ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="mid">建议价</el-dropdown-item><el-dropdown-item command="low">最低价</el-dropdown-item><el-dropdown-item command="high">最高价</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><span v-else>—</span></template></el-table-column><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-1', 'column-4', undefined)" :label="'竞价（'+currency+'）'" min-width="230" align="center"><template #default="{row}"><el-input-number  :model-value="row.bid??defaultBid" @update:model-value="(v:number|undefined)=>changeAutoBid(row,v)" :min="0.02" :max="10000" :precision="2" :step="0.01" controls-position="right" :aria-label="row.label+'竞价'" placeholder="请先填写默认竞价"/><el-button v-if="row.bid!=null" link @click="row.bid=undefined">恢复默认</el-button></template></el-table-column></el-table></template></template>
 <template v-else><el-radio-group v-model="manualType"><el-radio-button value="keywords">关键词投放（{{keywords.length}}）</el-radio-button><el-radio-button value="products">商品投放（{{targets.length}}）</el-radio-button></el-radio-group>
 <div v-if="manualType==='keywords'" class="keyword-editor">
 <div class="keyword-entry"><el-alert v-if="keywordInputError" :title="keywordInputError" type="error" :closable="false"/><el-checkbox-group v-model="keywordMatches" aria-label="关键词匹配方式"><el-checkbox v-for="m in ['EXACT','PHRASE','BROAD']" :key="m" :value="m">{{matchLabels[m]}}</el-checkbox></el-checkbox-group><el-input v-model="keywordText" type="textarea" :rows="4" placeholder="每行一个关键词"/><div class="section-actions"><el-button :icon="Plus" @click="addKeywords(false)">添加关键词</el-button><span class="hint">添加竞价 {{money(defaultBid)}}</span></div></div>
 <div class="keyword-bulk"><span>批量定价</span><el-select v-model="bulkScope" aria-label="批量定价范围" style="width:155px"><el-option :label="'全部 '+keywords.length+' 项'" value="all"/><el-option :label="'已选 '+chosenKeywords.length+' 项'" value="selected"/></el-select><el-button v-for="[key,label] in bidLevels" :key="key" :disabled="!batchKeywords.length" @click="applyKeywordBids(key)">应用{{label}}</el-button><el-input-number v-model="bulkBid" aria-label="自定义批量竞价" :min="0.02" :max="10000" :precision="2" :step="0.01" controls-position="right" placeholder="自定义竞价"/><el-button :disabled="!batchKeywords.length" @click="applyKeywordBids('custom')">应用自定义价</el-button><el-button :icon="Refresh" :loading="suggestBusy" :disabled="!keywords.length" @click="refreshSuggestions(false)">刷新建议竞价</el-button></div>
 <div class="keyword-bulk keyword-percent"><span>按当前竞价</span><el-select v-model="bulkDirection" aria-label="竞价百分比调整方向" style="width:110px"><el-option label="提高" value="increase"/><el-option label="降低" value="decrease"/></el-select><el-input-number v-model="bulkPercent" aria-label="竞价调整百分比" :min="0" :max="bulkDirection==='decrease'?99.99:10000" :precision="2" :step="5" controls-position="right" placeholder="调整幅度"/><span>%</span><el-button :disabled="!batchKeywords.length" @click="applyKeywordPercent">应用百分比</el-button><span class="hint">按上方所选范围，基于每项当前竞价调整。</span></div>
 <el-table class="keyword-table" border :data="keywords" :row-key="keywordKey" max-height="420" @selection-change="(v:any[])=>chosenKeywords=v"><el-table-column type="selection" width="45"/><el-table-column prop="text" label="关键词" min-width="200"/><el-table-column label="匹配" width="115"><template #default="{row}">{{matchLabels[row.match]}}</template></el-table-column><el-table-column :label="'建议竞价（'+currency+'）'" align="center" min-width="330"><template #default="{row}"><div class="keyword-bid-levels"><el-button v-for="[key,label] in bidLevels" :key="key" :disabled="!keywordSuggestions[keywordKey(row)]" @click="row.bid=keywordSuggestions[keywordKey(row)][key]"><span>{{label}}</span><b>{{money(keywordSuggestions[keywordKey(row)]?.[key])}}</b></el-button></div></template></el-table-column><el-table-column label="竞价" width="200" align="center"><template #default="{row}"><el-input-number v-model="row.bid" :aria-label="'竞价 '+row.text+' '+row.match" :min="0.02" :max="10000" :precision="2" :step="0.01" controls-position="right"/></template></el-table-column><el-table-column width="75"><template #default="{$index}"><el-button link @click="keywords.splice($index,1)">移除</el-button></template></el-table-column></el-table>
