 <div v-else class="entry-columns"><div><el-input v-model="targetText" type="textarea" :rows="7" placeholder="输入目标商品ASIN，每行一个"/><el-button :icon="Plus" @click="addAsins(false)">添加商品投放</el-button><TableReset table-key="AdsCreatePage/table-3"/></div><template v-if="true"><el-table border data-width-key="AdsCreatePage/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="targets" max-height="330"><el-table-column :column-key="'asin'" :width="tableWidths.width('table-3', 'asin', undefined)" prop="asin" label="目标ASIN"/><el-table-column :column-key="'column-2'" label="竞价" :width="tableWidths.width('table-3', 'column-2', '170')" align="center"><template #default="{row}"><el-input-number v-model="row.bid" :min="0.02" :precision="2" :step="0.01" controls-position="right" placeholder="默认"/></template></el-table-column><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-3', 'column-3', '60')"><template #default="{$index}"><el-button link @click="targets.splice($index,1)">移除</el-button></template></el-table-column></el-table></template></div></template>
 </section>
 <section class="create-card"><h3>否定关键词 <span class="hint">可选</span></h3><div class="entry-columns"><div><el-checkbox-group v-model="negativeMatches" aria-label="否定匹配方式"><el-checkbox value="NEGATIVE_EXACT">否定精准</el-checkbox><el-checkbox value="NEGATIVE_PHRASE">否定词组</el-checkbox></el-checkbox-group><el-input v-model="negativeText" type="textarea" :rows="7" placeholder="每行一个，最多1000个"/><el-button @click="addKeywords(true)">添加否定词</el-button></div><div><div class="section-actions"><span>已添加 {{negativeKeywords.length}} 个</span><el-button link @click="negativeKeywords=[]">全部移除</el-button><TableReset table-key="AdsCreatePage/table-4"/></div><template v-if="true"><el-table border data-width-key="AdsCreatePage/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="negativeKeywords" max-height="300"><el-table-column :column-key="'text'" :width="tableWidths.width('table-4', 'text', undefined)" prop="text" label="关键词"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-4', 'column-2', undefined)" label="匹配类型"><template #default="{row}">{{matchLabels[row.match]}}</template></el-table-column><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-4', 'column-3', '70')"><template #default="{$index}"><el-button link @click="negativeKeywords.splice($index,1)">移除</el-button></template></el-table-column></el-table></template></div></div></section>
